// The platform sets:
// const students = [
//     { name: "Anna", score: 92 },
//     { name: "Timur", score: 78 },
//     { name: "Lola", score: 65 },
//     { name: "Sardor", score: 95 },
// ];
// The functions will also be checked on other arrays, including an empty one.

// 1. getAverage(list) - reduce, Math.round, empty array → 0

// 2. getExcellentNames(list) - filter + map, names with a score from 90

// 3. findStudent(list, name) - find

// 4. addStudent(list, name, score) - a new array with ...

task.setup:
const students = [
    { name: "Anna", score: 92 },
    { name: "Timur", score: 78 },
    { name: "Lola", score: 65 },
    { name: "Sardor", score: 95 },
];

task.solution:
function getAverage(list) {
    if (list.length === 0) {
        return 0;
    }
    const total = list.reduce((sum, student) => sum + student.score, 0);
    return Math.round(total / list.length);
}

function getExcellentNames(list) {
    return list
        .filter((student) => student.score >= 90)
        .map((student) => student.name);
}

function findStudent(list, name) {
    return list.find((student) => student.name === name);
}

function addStudent(list, name, score) {
    return [...list, { name, score }];
}

console.log(getAverage(students), getExcellentNames(students));

